import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint128 _putAmount, uint256 _unlockTime) public {
        // Use a fresh address to avoid state interference across fuzz runs
        address actor = address(uint160(uint256(keccak256(abi.encodePacked(_putAmount, _unlockTime)))));
        // Ensure the unlockTime is in the future so a subsequent Collect can succeed
        vm.warp(1);
        uint256 unlock = _unlockTime > block.timestamp ? _unlockTime : block.timestamp;
        // Fund the actor and call Put via prank
        vm.deal(actor, type(uint128).max);
        uint256 val = uint256(_putAmount);
        // Bound val to prevent overflow in sum (keep sum within uint256)
        vm.assume(val <= type(uint128).max / 2);
        // First Put
        vm.prank(actor);
        c.Put{value: val}(unlock);
        // Second Put (so sum of sent values is distinct)
        uint256 val2 = val + 1;
        vm.assume(val2 <= type(uint128).max / 2);
        vm.prank(actor);
        c.Put{value: val2}(unlock);
        // Get the Actor's balance and the sum of sent values
        ( , uint256 accBal) = c.Acc(actor);
        uint256 totalSent = val + val2;
        // Rule: The account's balance in the contract must equal the total Ether the actor sent via Put
        // The mutant omits the balance update, so accBal remains 0 while totalSent > 0, violating equality
        assertTrue(accBal == totalSent);
    }
}

